import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Example domain — support ticket intake","description":"","frontmatter":{},"headers":[],"relativePath":"build/example.md","filePath":"build/example.md"}`),a={name:`build/example.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="example-domain-—-support-ticket-intake" tabindex="-1">Example domain — support ticket intake <a class="header-anchor" href="#example-domain-—-support-ticket-intake" aria-label="Permalink to “Example domain — support ticket intake”">​</a></h1><p>The smallest honest domain: everything a real one has, nothing invented.</p><table tabindex="0"><thead><tr><th>Part</th><th>File</th><th>What it shows</th></tr></thead><tbody><tr><td>Manifest</td><td><code>domain.json</code></td><td>the router card, steps order, slot labels, the entity name, the mock policy</td></tr><tr><td>Tools</td><td><code>mcp/server.ts</code></td><td>reads (<code>search_customers</code>, <code>reference_data</code>), the triad (<code>validate_ticket_slots</code> fills from the record and applies defaults, <code>preview_ticket</code>, <code>create_ticket</code> with the write gate), <code>internal_*</code> media tools, the <code>reg()</code> wrapper (auth + trace context from <code>_meta</code>)</td></tr><tr><td>Skill</td><td><code>skills/support-intake/SKILL.md</code></td><td>entry, the customer cascade (picker on ≥2 matches), the category ask, what the runtime owns</td></tr><tr><td>Schema</td><td><code>schema/ticket-schema.json</code></td><td>slots with sources, mandatory sets, ask sets, runtime steps, probe findings</td></tr><tr><td>Steps</td><td><code>steps/index.ts</code></td><td>a form step (Details) and a chips step (Priority) from <code>stepHelpers</code></td></tr><tr><td>Mock</td><td><code>mock/policy.ts</code></td><td>the model&#39;s part of the journey as a state machine — the offline path</td></tr><tr><td>Evals</td><td><code>evals/run-evals.ts</code></td><td>seven scenarios: happy path, confirm gate, words beside a form, partial form, the review, injection, summary defaults</td></tr><tr><td>Fixtures</td><td><code>fixtures/customers.json</code></td><td>reference data with two look-alike names (the picker)</td></tr></tbody></table><p>Try it: <code>npm run gateway</code>, open <a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a>, type <em>&quot;ticket for Northwind: login fails on mobile&quot;</em>. Data lands in <code>examples/support-intake/.data/</code> (tickets.json, uploads) when writes are on.</p><p>Copy it: <code>npm run new-domain -- &lt;name&gt;</code> scaffolds from <code>templates/</code>, or copy this folder into <code>domains/&lt;name&gt;</code> and replace the backend behind the tools.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/examples/support-intake/README.md">examples/support-intake/README.md</a> — edit it there; the site mirrors the repository.</small></p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};